/* The per-row edit panel lives in the last table cell. Opened in place it is squeezed to one
   character per line on a phone and runs off the right edge on desktop (the row of fields is
   wider than the viewport), and an overlay anchored to the cell loses hit-testing to the rows
   below it. Instead the open panel docks as a bottom sheet: fixed to the viewport (the table's
   layout and stacking cannot clip or cover it), capped in height and scrollable so the
   keyboard or a short viewport cannot hide its controls. The close control only collapses it. */
table.scope-t details.scope-edit[open] form {
  position:fixed; left:8px; right:8px; bottom:8px; top:auto;
  max-height:70vh; overflow-y:auto;
  background:#fff; border:1px solid #888; border-radius:8px; padding:10px; z-index:70;
  box-shadow:0 -2px 14px rgba(0,0,0,.3); white-space:normal; text-align:left;
}
@media (min-width: 641px) {
  table.scope-t details.scope-edit[open] form { left:auto; right:16px; width:min(680px, calc(100vw - 32px)); }
}

@media (max-width: 640px) {
  header nav { display:none; }
  header.nav-open nav { display:flex; position:absolute; top:100%; left:0; right:0; background:var(--bg); border-bottom:1px solid var(--line); padding:6px; z-index:10; max-height:60vh; overflow-y:auto; }
  main.split { display:block; }
  main.split #list { width:100%; border-right:none; max-height:55vh; }
  main.split #detail { width:100%; }
  #nav-burger { display:inline-block; }
  table { table-layout:fixed; }
  th, td { max-width:none; }
  header { padding:6px 8px; gap:6px; }
  header form { margin-left:0; width:100%; }
  header form input { flex:1; min-width:0; }
  #list { overflow-x:hidden; }
  body { overflow-x:hidden; }
  /* Wide traffic tables (History, Logger - class wide-t) cull their edge columns on a phone.
     Heading and body must hide together and only on those tables: the old #rows-wide rule hit
     every fragment's thead inside #rows, so pages like WebSockets lost their first TH while the
     TD stayed, shifting every label one column left. */
  table.wide-t td:nth-child(1), table.wide-t th:nth-child(1),
  table.wide-t td:nth-child(8), table.wide-t th:nth-child(8) { display:none; }
  /* ...but the lazy-load sentinel is not column content: its single colspan cell also matches
     nth-child(1), and culled to zero size its intersect trigger can never fire on a phone. */
  table.wide-t tr.sentinel-row td { display:table-cell; }
  /* Scope table: on a phone the Path and Protocol columns drop out and the per-row action
     buttons wrap inside their cell, so Remove stays reachable instead of clipping off-screen. */
  table.scope-t td:nth-child(4), table.scope-t th:nth-child(4),
  table.scope-t td:nth-child(6), table.scope-t th:nth-child(6) { display:none; }
  /* Fixed table layout sizes columns from the header row, so the action column gets an
     explicit width: wide enough for each control on one line, while Host truncates by design. */
  table.scope-t th:last-child { width:112px; }
  table.scope-t td.sa { white-space:normal; position:relative; }

  /* Buttons and the edit summary are controls, not text to wrap: keep each on one line even
     when tap-to-expand selects the row (cell-x would otherwise break them one char per line). */
  table.scope-t td.sa button, table.scope-t td.sa summary { white-space:nowrap; }
  table.scope-t td.sa.cell-x { word-break:normal; }
  /* Site map: ten columns cannot fit a phone, so the count/detail columns (Exch, Subtree,
     Methods, Statuses, MIME, Issues) drop out and depth/Path/Scope/Actions remain. Without
     this the fixed-layout cells overlap and the Actions links intercept each other's taps
     (QA D1-phone-1). The counts stay one tap away on desktop-width. */
  table.sitemap-t td:nth-child(3), table.sitemap-t th:nth-child(3),
  table.sitemap-t td:nth-child(4), table.sitemap-t th:nth-child(4),
  table.sitemap-t td:nth-child(5), table.sitemap-t th:nth-child(5),
  table.sitemap-t td:nth-child(6), table.sitemap-t th:nth-child(6),
  table.sitemap-t td:nth-child(7), table.sitemap-t th:nth-child(7),
  table.sitemap-t td:nth-child(8), table.sitemap-t th:nth-child(8) { display:none; }
  table.sitemap-t th:last-child { width:120px; }
  /* The Actions links wrap inside their 120px column rather than overflow it: a nowrap
     "Send to Repeater" is ~132px and body overflow-x:hidden clips the label off-screen
     with no scroll escape (QA residual after the tap fix). Two short lines beat a clipped
     button - the full label stays visible and the tap target only gets taller. */
  table.sitemap-t td:last-child { white-space:normal; }
  table.sitemap-t td:last-child .btn { white-space:normal; display:block; }
  table.scope-t tr.scope-sd { display:table-row; }
  /* Session rules table: same phone treatment as scope-t (caught live in UAT - at 390px the
     inline toggle form overlapped the remove button and made it untappable). The Tools and
     action-label columns drop out; the per-row controls stack one per line so every one stays
     inside the cell's tap area. */
  table.rules-t td:nth-child(4), table.rules-t th:nth-child(4),
  table.rules-t td:nth-child(5), table.rules-t th:nth-child(5) { display:none; }
  table.rules-t th:last-child { width:120px; }
  table.rules-t td.sa { white-space:normal; position:relative; }
  table.rules-t td.sa form { display:block; margin:2px 0; }
  table.rules-t td.sa button, table.rules-t td.sa summary { white-space:nowrap; }

  /* Tap-to-expand: a truncated cell expands in place so its full content wraps
     visibly; tapping it again collapses. */
  tbody tr.selected td { cursor:zoom-in; }
  td.cell-x { white-space:normal; word-break:break-all; overflow:visible; cursor:zoom-out; }
  thead th.cell-x { white-space:normal; overflow-wrap:break-word; overflow:visible; cursor:zoom-out; }
  thead th[tabindex] { cursor:zoom-in; }
  .phone-hint { display:block; }
}

