<body data-view="{{.View}}">
<header>
  <span class="brand">burpsy <span class="badge">ui2</span></span>
  <button id="nav-burger" class="btn" aria-label="Open navigation menu" aria-expanded="false">☰</button>
  {{template "nav" .}}
  <span id="sel-count" class="meta" aria-live="polite"></span>
  <span id="busybadge" class="meta" hidden>working&hellip;</span>
  <button id="theme-toggle" class="btn" aria-label="Toggle light/dark theme" title="Toggle theme">◐</button>
  {{if eq .View "history"}}
  <form hx-get="/ui2/history" hx-target="#rows" hx-swap="outerHTML" hx-trigger="submit, keyup changed delay:400ms from:#q" hx-push-url="true">
    <input type="search" id="q" name="q" aria-label="Filter query (burpsy DSL, e.g. host~example.com)" placeholder="filter: host~example.com path~/api" autocomplete="off">
    <input type="search" name="search" aria-label="Search rows" placeholder="search…" autocomplete="off"
      hx-get="/ui2/history" hx-target="#rows" hx-swap="outerHTML" hx-trigger="keyup changed delay:400ms" hx-include="#q" hx-push-url="true">
    <noscript><button>Filter</button></noscript>
  </form>
  {{end}}
</header>
<div id="notice" role="status" aria-live="polite"></div>
<main class="{{if or (eq .View "history") (eq .View "issues") (eq .View "intruder") (eq .View "advisories")}}split{{end}}">
  <div id="list" role="region" aria-label="Rows">
    {{.Body}}
  </div>
  <div id="detail" role="region" aria-label="Selected item detail" aria-live="polite">{{if eq .View "history"}}<p class="meta">Select a row to see its request and response.</p>{{end}}</div>
</main>
<script src="/ui2/htmx.min.js"></script>
<script src="/ui2/app.js"></script>
</body>
</html>

