    }
  });
})();

// ---- Row multi-select (checkbox column driven by .checked class) ----
(function () {
  function count() {
    var n = document.querySelectorAll('#rows-body tr.checked').length;
    var el = document.getElementById('sel-count');
    if (el) el.textContent = n ? n + ' selected' : '';
