	{ID: "proxy", Label: "Proxy history"},
	{ID: "crawler", Label: "Crawler"},
	{ID: "repeater", Label: "Repeater"},
	{ID: "intruder", Label: "Intruder"},
	{ID: "scanner", Label: "Scanner"},
